import {Dialog} from '@primer/react'

export interface DisableAdvancedSecurityDialogProps {
  isDisabling: boolean
  onConfirmed: () => void
  onClose: () => void
}

export function DisableAdvancedSecurityDialog({isDisabling, onConfirmed, onClose}: DisableAdvancedSecurityDialogProps) {
  return (
    <Dialog
      title="Disable Advanced Security for this enterprise"
      onClose={onClose}
      footerButtons={[
        {
          buttonType: 'default',
          onClick: onClose,
          content: 'Cancel',
          disabled: isDisabling,
        },
        {
          'aria-disabled': isDisabling,
          buttonType: 'danger',
          loading: isDisabling,
          onClick: onConfirmed,
          content: isDisabling ? 'Disabling...' : 'Disable Advanced Security',
        },
      ]}
      renderBody={() => (
        <Dialog.Body>
          <p>
            This will disable Advanced Security, including Secret Protection and Code Security for private and internal
            repositories.
          </p>
          <ul className="tmp-mt-3 tmp-pl-4">
            <li className="tmp-mb-2">Public repositories will remain protected for free</li>
            <li className="tmp-mb-2">
              Organizations and repositories will be blocked from enabling Advanced Security features in private and
              internal repositories
            </li>
          </ul>
          <p className="tmp-mt-3">
            To allow enablement in the future, you must update the policy under Advanced Security policies.
          </p>
        </Dialog.Body>
      )}
      role="alertdialog"
    />
  )
}
