import {verifiedFetchJSON} from '@github-ui/verified-fetch'

type DisableAdvancedSecurityResponse = {error: string} | {success: string}
type DisableAdvancedSecurityResult = {successMessage: string}

export async function disableAdvancedSecurity(disableButtonPath: string): Promise<DisableAdvancedSecurityResult> {
  const response = await verifiedFetchJSON(disableButtonPath, {method: 'DELETE'})

  if (!response.ok) {
    throw new Error('Sorry, we were unable to disable Advanced Security. Please try again.')
  }

  let result: DisableAdvancedSecurityResponse
  try {
    result = (await response.json()) as DisableAdvancedSecurityResponse
  } catch {
    throw new Error('Sorry, we were unable to disable Advanced Security. Please try again.')
  }

  if ('error' in result) {
    throw new Error(result.error)
  }

  if (!('success' in result)) {
    throw new Error('Sorry, we were unable to disable Advanced Security. Please try again.')
  }

  return {
    successMessage: result.success,
  }
}
