import {ActionList, ActionMenu} from '@primer/react'

import type {InvoiceLicenseInfo} from '@github-ui/licensing-common/types/invoice-license-info'
import type {TrialInfo} from '@github-ui/licensing-common/types/trial-info'
import styles from './AdvancedSecuritySummaryHeaderMenu.module.css'

export interface Props {
  canDisableGhas?: boolean
  eligibleForTrial: boolean
  isSelfServeAdvancedSecurity: boolean
  invoiceLicenseInfo?: InvoiceLicenseInfo
  isSelfServeVolume: boolean
  isStafftools: boolean
  isTeams: boolean
  trialInfo?: TrialInfo
  configureButtonPath: string
  onManageSeatsSelect: () => void
  onCancelSubscriptionSelect: () => void
  onDisableAdvancedSecuritySelect?: () => void
}

export function AdvancedSecuritySummaryHeaderMenu(props: Props) {
  // None of these actions should be available in stafftools or Teams
  if (props.isStafftools || props.isTeams) {
    return null
  }

  // Self-serve volume customers see: "Manage licenses", "Go to settings", "Cancel subscription"
  const isSelfServeVolume =
    !props.trialInfo &&
    !props.eligibleForTrial &&
    !props.invoiceLicenseInfo &&
    props.isSelfServeAdvancedSecurity &&
    props.isSelfServeVolume

  // Non-self-serve GHAS-enabled customers (metered or sales-led volume) see: "Go to settings", "Disable Advanced Security"
  // Self-serve volume exclusion is handled server-side in canDisableGhas.

  if (!isSelfServeVolume && !props.canDisableGhas) {
    return null
  }

  return (
    <ActionMenu>
      <ActionMenu.Button className={styles.manageButton} data-testid="ghas-summary-manage-button">
        Manage
      </ActionMenu.Button>
      <ActionMenu.Overlay width="medium">
        <ActionList data-testid="ghas-summary-menu">
          {isSelfServeVolume && (
            <ActionList.Item onSelect={props.onManageSeatsSelect} data-testid="ghas-summary-menu-manage-seats-item">
              Manage licenses
            </ActionList.Item>
          )}
          <ActionList.LinkItem href={props.configureButtonPath} data-testid="ghas-summary-menu-go-to-settings-item">
            Go to settings
          </ActionList.LinkItem>
          {isSelfServeVolume && (
            <ActionList.Item
              onSelect={props.onCancelSubscriptionSelect}
              data-testid="ghas-summary-menu-cancel-subscription-item"
            >
              Cancel subscription
            </ActionList.Item>
          )}
          {props.canDisableGhas && (
            <ActionList.Item
              onSelect={props.onDisableAdvancedSecuritySelect}
              data-testid="ghas-summary-menu-disable-item"
            >
              Disable Advanced Security
            </ActionList.Item>
          )}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}
